from __future__ import annotations

import importlib.util
import os
import unittest
import zipfile

from docx import Document
from lxml import etree

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCRIPT_PATH = os.path.join(ROOT_DIR, "src", "scripts", "build-tracked-docx.py")

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
CT_NS = "http://schemas.openxmlformats.org/package/2006/content-types"


def _wtag(name: str) -> str:
    return "{%s}%s" % (W_NS, name)


def _load_module():
    spec = importlib.util.spec_from_file_location("build_tracked_docx", SCRIPT_PATH)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


btd = _load_module()


def make_change(**overrides):
    change = {
        "stage": "mechanical",
        "line": 1,
        "type": "typo",
        "level": "word",
        "before": "טוב",
        "after": "נחמד",
        "rationale": "word choice",
        "meaningRisk": "low",
        "applied": True,
        "skipReason": None,
    }
    change.update(overrides)
    return change


class TrackedDocxTestCase(unittest.TestCase):
    """Shared fixture helpers."""

    def _build_original(self, paragraphs, seed_revision=False, seed_id=500):
        """Create a synthetic .docx with one paragraph per string in
        `paragraphs`, each as a single run. Optionally seed a pre-existing
        hand-built w:ins carrying a high w:id, to exercise id-collision
        avoidance (finding c)."""
        path = os.path.join(self.tmpdir, "original.docx")
        doc = Document()
        for text in paragraphs:
            doc.add_paragraph(text)
        doc.save(path)

        if seed_revision:
            with zipfile.ZipFile(path, "r") as zf:
                doc_xml = zf.read("word/document.xml")
            root = etree.fromstring(doc_xml)
            body = root.find(_wtag("body"))
            p = etree.SubElement(body, _wtag("p"))
            ins = etree.SubElement(p, _wtag("ins"))
            ins.set(_wtag("id"), str(seed_id))
            ins.set(_wtag("author"), "Hand Editor")
            ins.set(_wtag("date"), "2026-07-10T00:00:00Z")
            r = etree.SubElement(ins, _wtag("r"))
            t = etree.SubElement(r, _wtag("t"))
            t.text = "seeded revision text"
            # move the new paragraph to be first, so it sits alongside the
            # editable paragraphs rather than only at the end.
            body.remove(p)
            body.insert(0, p)
            new_xml = etree.tostring(root, xml_declaration=True, encoding="UTF-8", standalone=True)
            self._rewrite_zip_entry(path, "word/document.xml", new_xml)

        return path

    @staticmethod
    def _rewrite_zip_entry(zip_path, entry_name, new_bytes):
        import shutil
        import tempfile

        tmp_fd, tmp_path = tempfile.mkstemp()
        os.close(tmp_fd)
        with zipfile.ZipFile(zip_path, "r") as zin, zipfile.ZipFile(tmp_path, "w", zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                data = zin.read(item.filename)
                if item.filename == entry_name:
                    data = new_bytes
                zout.writestr(item, data)
        shutil.move(tmp_path, zip_path)

    def setUp(self):
        import tempfile

        self._tmpdir_ctx = tempfile.TemporaryDirectory()
        self.tmpdir = self._tmpdir_ctx.name

    def tearDown(self):
        self._tmpdir_ctx.cleanup()

    def _document_root(self, docx_path):
        with zipfile.ZipFile(docx_path, "r") as zf:
            doc_xml = zf.read("word/document.xml")
        return etree.fromstring(doc_xml)

    def _reconstruct_final_text(self, root):
        """Accept every tracked change: walk the XML, take w:ins content,
        drop w:del content, keep everything else. Returns paragraph texts
        joined by '\\n'."""
        body = root.find(_wtag("body"))
        paragraphs = body.findall(_wtag("p"))
        out = []
        for p in paragraphs:
            parts = []
            for t in p.iter(_wtag("t")):
                if self._is_in_del(t):
                    continue
                parts.append(t.text or "")
            out.append("".join(parts))
        return "\n".join(out)

    @staticmethod
    def _is_in_del(node):
        parent = node.getparent()
        while parent is not None:
            if etree.QName(parent).localname == "del":
                return True
            if etree.QName(parent).localname == "p":
                return False
            parent = parent.getparent()
        return False

    def _count_tags(self, root, tag):
        return len(list(root.iter(_wtag(tag))))


class AcceptAllReconstructionTests(TrackedDocxTestCase):
    def test_accept_all_reconstructs_final_text_exactly(self):
        original_path = self._build_original(["שלום עולם טוב היום", "שורה שנייה ללא שינוי"])
        final_text = "שלום עולם נחמד היום\nשורה שנייה ללא שינוי"
        changes = [make_change()]
        output_path = os.path.join(self.tmpdir, "original.proofed.docx")

        result = btd.build_tracked_docx(original_path, final_text, changes, output_path)

        self.assertTrue(result["written"])
        self.assertTrue(os.path.exists(output_path))

        root = self._document_root(output_path)
        reconstructed = self._reconstruct_final_text(root)
        self.assertEqual(reconstructed, final_text)


class CountsAndAuthorTests(TrackedDocxTestCase):
    def test_ins_del_comment_counts_and_authors_match_stage_map(self):
        original_path = self._build_original(
            [
                "שלום עולם טוב היום",
                "פרופ׳ כתב מאמר חדש בנושא",
            ]
        )
        final_text = "שלום עולם נחמד היום\nפרופ׳ כתב מאמר חדש בנושא"
        changes = [
            make_change(stage="mechanical", before="טוב", after="נחמד"),
            make_change(
                stage="editorial",
                type="genre-fit",
                level="idea",
                before="כתב מאמר",
                after=None,
                rationale="editorial finding: reconsider framing",
                meaningRisk="high",
                applied=False,
                skipReason=None,
            ),
        ]
        output_path = os.path.join(self.tmpdir, "original.proofed.docx")

        result = btd.build_tracked_docx(original_path, final_text, changes, output_path)

        self.assertEqual(result["counts"], {"ins": 1, "del": 1, "comment": 1})
        self.assertEqual(result["skipped"], [])

        root = self._document_root(output_path)
        self.assertEqual(self._count_tags(root, "ins"), 1)
        self.assertEqual(self._count_tags(root, "del"), 1)
        self.assertEqual(self._count_tags(root, "commentReference"), 1)

        ins_el = next(root.iter(_wtag("ins")))
        del_el = next(root.iter(_wtag("del")))
        self.assertEqual(ins_el.get(_wtag("author")), "Proofreader (Claude)")
        self.assertEqual(del_el.get(_wtag("author")), "Proofreader (Claude)")

        with zipfile.ZipFile(output_path, "r") as zf:
            comments_xml = etree.fromstring(zf.read("word/comments.xml"))
        comment_el = next(comments_xml.iter(_wtag("comment")))
        self.assertEqual(comment_el.get(_wtag("author")), "Editor (Claude)")
        comment_text = "".join(t.text or "" for t in comment_el.iter(_wtag("t")))
        self.assertEqual(comment_text, "editorial finding: reconsider framing")

    def test_medium_risk_language_change_becomes_comment_not_edit(self):
        original_path = self._build_original(["המחקר הזה חשוב מאוד לתחום"])
        final_text = "המחקר הזה חשוב מאוד לתחום"
        changes = [
            make_change(
                stage="language",
                type="register",
                level="sentence",
                before="חשוב מאוד",
                after="בעל חשיבות ניכרת",
                rationale="register shift risks tone",
                meaningRisk="medium",
                applied=False,
                skipReason=None,
            )
        ]
        output_path = os.path.join(self.tmpdir, "original.proofed.docx")

        result = btd.build_tracked_docx(original_path, final_text, changes, output_path)

        self.assertEqual(result["counts"], {"ins": 0, "del": 0, "comment": 1})
        root = self._document_root(output_path)
        self.assertEqual(self._count_tags(root, "ins"), 0)
        self.assertEqual(self._count_tags(root, "del"), 0)
        self.assertEqual(self._count_tags(root, "commentReference"), 1)


class IdCollisionTests(TrackedDocxTestCase):
    def test_new_ids_exceed_seeded_high_id(self):
        original_path = self._build_original(
            ["שלום עולם טוב היום"], seed_revision=True, seed_id=500
        )
        final_text = "\nשלום עולם נחמד היום"
        # The seeded revision paragraph is inserted first, so the editable
        # paragraph is now at index 1; final_text has a matching (ignored,
        # since the seeded paragraph is never diffed) empty first line.
        changes = [make_change()]
        output_path = os.path.join(self.tmpdir, "original.proofed.docx")

        result = btd.build_tracked_docx(original_path, final_text, changes, output_path)
        self.assertTrue(result["written"])

        root = self._document_root(output_path)
        all_ids = [int(v) for v in root.xpath("//*[@w:id]/@w:id", namespaces={"w": W_NS})]
        new_ids = [i for i in all_ids if i != 500]
        self.assertTrue(new_ids, "expected at least one newly allocated id")
        self.assertTrue(all(i > 500 for i in new_ids), f"new ids collide with/undercut seed: {all_ids}")

        # the seeded revision paragraph must be untouched (finding a).
        seeded_ins = root.xpath("//*[@w:id='500']", namespaces={"w": W_NS})
        self.assertEqual(len(seeded_ins), 1)
        self.assertEqual(seeded_ins[0].get(_wtag("author")), "Hand Editor")


class WiringTests(TrackedDocxTestCase):
    def test_comments_part_present_and_wired(self):
        original_path = self._build_original(["פרופ׳ כתב מאמר חדש בנושא"])
        final_text = "פרופ׳ כתב מאמר חדש בנושא"
        changes = [
            make_change(
                stage="editorial",
                type="genre-fit",
                level="idea",
                before="כתב מאמר",
                after=None,
                rationale="reconsider framing",
                meaningRisk="high",
                applied=False,
                skipReason=None,
            )
        ]
        output_path = os.path.join(self.tmpdir, "original.proofed.docx")

        result = btd.build_tracked_docx(original_path, final_text, changes, output_path)
        self.assertEqual(result["counts"]["comment"], 1)

        with zipfile.ZipFile(output_path, "r") as zf:
            names = zf.namelist()
            self.assertIn("word/comments.xml", names)

            ct_root = etree.fromstring(zf.read("[Content_Types].xml"))
            overrides = [
                el.get("PartName")
                for el in ct_root
                if etree.QName(el).localname == "Override"
            ]
            self.assertIn("/word/comments.xml", overrides)

            rels_root = etree.fromstring(zf.read("word/_rels/document.xml.rels"))
            targets = [
                el.get("Target")
                for el in rels_root
                if etree.QName(el).localname == "Relationship"
            ]
            self.assertIn("comments.xml", targets)


class NoMatchSkipTests(TrackedDocxTestCase):
    def test_change_with_before_not_found_is_skipped_and_document_unaffected(self):
        original_path = self._build_original(["שלום עולם טוב היום"])
        final_text = "שלום עולם טוב היום"
        changes = [
            make_change(before="מילה שלא קיימת בטקסט", after="תיקון", applied=True),
        ]
        output_path = os.path.join(self.tmpdir, "original.proofed.docx")

        result = btd.build_tracked_docx(original_path, final_text, changes, output_path)

        self.assertEqual(len(result["skipped"]), 1)
        self.assertEqual(result["skipped"][0]["reason"], "no-match")
        self.assertEqual(result["counts"], {"ins": 0, "del": 0, "comment": 0})

        # Document is byte-comparable to a run with no changes at all
        # (equivalent to the "no-changes" clean-pass output structurally --
        # no ins/del/comment anywhere, original text intact).
        root = self._document_root(output_path)
        self.assertEqual(self._count_tags(root, "ins"), 0)
        self.assertEqual(self._count_tags(root, "del"), 0)
        reconstructed = self._reconstruct_final_text(root)
        self.assertEqual(reconstructed, final_text)

    def test_skip_leaves_document_byte_comparable_to_omitting_the_change(self):
        original_path = self._build_original(["שלום עולם טוב היום"])
        final_text = "שלום עולם נחמד היום"
        good_change = make_change(before="טוב", after="נחמד")
        bad_change = make_change(before="לא קיים", after="תיקון")
        output_with_bad = os.path.join(self.tmpdir, "with_bad.proofed.docx")
        output_without_bad = os.path.join(self.tmpdir, "without_bad.proofed.docx")

        btd.build_tracked_docx(original_path, final_text, [good_change, bad_change], output_with_bad)
        btd.build_tracked_docx(original_path, final_text, [good_change], output_without_bad)

        with zipfile.ZipFile(output_with_bad) as zf:
            xml_with_bad = zf.read("word/document.xml")
        with zipfile.ZipFile(output_without_bad) as zf:
            xml_without_bad = zf.read("word/document.xml")
        self.assertEqual(xml_with_bad, xml_without_bad)


class EmptyChangesTests(TrackedDocxTestCase):
    def test_empty_change_list_produces_no_output_file_and_clean_report(self):
        original_path = self._build_original(["שלום עולם טוב היום"])
        output_path = os.path.join(self.tmpdir, "should_not_exist.proofed.docx")

        result = btd.build_tracked_docx(original_path, "שלום עולם טוב היום", [], output_path)

        self.assertFalse(result["written"])
        self.assertIsNone(result["output_path"])
        self.assertEqual(result["reason"], "no-changes")
        self.assertEqual(result["counts"], {"ins": 0, "del": 0, "comment": 0})
        self.assertEqual(result["skipped"], [])
        self.assertFalse(os.path.exists(output_path))

