class CliTests(TrackedDocxTestCase):
    def test_cli_writes_output_and_prints_json_report(self):
        import json
        import subprocess
        import sys

        original_path = self._build_original(["שלום עולם טוב היום"])
        final_text_path = os.path.join(self.tmpdir, "final.txt")
        with open(final_text_path, "w", encoding="utf-8") as f:
            f.write("שלום עולם נחמד היום")

        changes_path = os.path.join(self.tmpdir, "changes.json")
        with open(changes_path, "w", encoding="utf-8") as f:
            json.dump([make_change()], f, ensure_ascii=False)

        output_path = os.path.join(self.tmpdir, "cli_output.proofed.docx")

        proc = subprocess.run(
            [
                sys.executable,
                SCRIPT_PATH,
                "--original",
                original_path,
                "--final-text",
                final_text_path,
                "--changes",
                changes_path,
                "--output",
                output_path,
            ],
            capture_output=True,
            text=True,
            timeout=30,
        )

        self.assertEqual(proc.returncode, 0, proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertTrue(payload["written"])
        self.assertTrue(os.path.exists(output_path))


